/* eslint-disable react/require-default-props */
import React, { HTMLProps } from 'react';
import {
  CharacterCounter,
  Error,
  ErrorIcon,
  Hint,
  Label,
  LabelContainer,
  Legend,
  OptionalIndicator,
  Container,
} from './Input/Input.styles';

export interface InputWrapperProps {
  label?: string;
  hint?: string;
  characterCounter?: boolean;
  required?: boolean;
  legend?: string;
  children: React.ReactNode;
  optionalText?: string;
  hasError?: boolean;
  disabled?: boolean;
  errorText?: string;
  labelProps?: HTMLProps<HTMLLabelElement>;
  counter?: number;
  maxCounter?: number;
  width?: string | number;
}

export const InputWrapper = ({
  characterCounter = false,
  hint,
  label,
  legend,
  required = true,
  children,
  optionalText,
  hasError = false,
  disabled = false,
  errorText = '',
  labelProps,
  counter,
  maxCounter,
  width,
}: InputWrapperProps): JSX.Element => (
  <Container css={{ width }}>
    {legend ? <Legend>{legend}</Legend> : null}
    {label ? (
      <LabelContainer>
        <Label htmlFor={labelProps?.htmlFor} hasError={hasError} disabled={disabled}>
          {label}
        </Label>
        {!required ? <OptionalIndicator>{optionalText}</OptionalIndicator> : null}
      </LabelContainer>
    ) : null}
    {hint ? <Hint>{hint}</Hint> : null}
    {hasError ? (
      <Error>
        <ErrorIcon size="tiny" />
        {errorText}
      </Error>
    ) : null}
    {children}
    {characterCounter && maxCounter ? (
      <CharacterCounter>{`${counter}/${maxCounter}`}</CharacterCounter>
    ) : null}
  </Container>
);

export default InputWrapper;
